import { describe, expect, it } from 'vitest';
import {
  checkFileMeta,
  countMarkers,
  detectFormat,
  inspectGenomeFile,
  MAX_FILE_SIZE_BYTES,
} from './fileValidation';

const SAMPLE_23ANDME = [
  '# This data file generated by 23andMe',
  '# rsid\tchromosome\tposition\tgenotype',
  'rs7903146\t10\t114758349\tCT',
  'rs429358\t19\t45411941\tTT',
  'i3000001\tMT\t146\t--',
].join('\n');

describe('checkFileMeta', () => {
  it('приймає текстовий файл потрібного розміру', () => {
    expect(checkFileMeta('genome.txt', 1024)).toBeNull();
    expect(checkFileMeta('GENOME.VCF', 1024)).toBeNull();
  });

  it('відхиляє непідтримуване розширення', () => {
    expect(checkFileMeta('photo.png', 1024)).toContain('непідтримуваний формат');
  });

  it('відхиляє порожній файл', () => {
    expect(checkFileMeta('genome.txt', 0)).toContain('порожній');
  });

  it('відхиляє файл, більший за 50 МБ', () => {
    expect(checkFileMeta('genome.txt', MAX_FILE_SIZE_BYTES + 1)).toContain('50 МБ');
  });
});

describe('detectFormat', () => {
  it('розпізнає 23andMe', () => {
    expect(detectFormat(SAMPLE_23ANDME)).toBe('23andme');
  });

  it('розпізнає VCF', () => {
    expect(detectFormat('##fileformat=VCFv4.2\n#CHROM\tPOS\tID\n10\t114758349\trs7903146')).toBe('vcf');
  });

  it('розпізнає AncestryDNA', () => {
    const text = '#AncestryDNA raw data\nrsid\tchromosome\tposition\tallele1\tallele2\nrs4477212\t1\t82154\tA\tA';
    expect(detectFormat(text)).toBe('ancestry');
  });

  it('розпізнає MyHeritage', () => {
    const text = '# MyHeritage DNA raw data\n"RSID","CHROMOSOME","POSITION","RESULT"\n"rs4477212","1","82154","AA"';
    expect(detectFormat(text)).toBe('myheritage');
  });

  it('повертає null для довільного тексту', () => {
    expect(detectFormat('Привіт, це не ДНК')).toBeNull();
  });

  it('працює з віндовськими кінцями рядків', () => {
    expect(detectFormat(SAMPLE_23ANDME.replace(/\n/g, '\r\n'))).toBe('23andme');
  });
});

describe('countMarkers', () => {
  it('не рахує коментарі, порожні рядки й заголовки', () => {
    expect(countMarkers(`${SAMPLE_23ANDME}\n\n`)).toBe(3);
    expect(countMarkers('rsid\tchromosome\tposition\tallele1\tallele2\nrs1\t1\t1\tA\tA')).toBe(1);
  });
});

describe('inspectGenomeFile', () => {
  it('повертає формат і кількість маркерів для коректного файлу', async () => {
    const file = new File([SAMPLE_23ANDME], 'genome.txt', { type: 'text/plain' });
    expect(await inspectGenomeFile(file)).toEqual({ ok: true, format: '23andme', markerCount: 3 });
  });

  it('повертає помилку, якщо вміст не схожий на генотип', async () => {
    const file = new File(['name,age\nAnna,20'], 'table.csv', { type: 'text/csv' });
    const result = await inspectGenomeFile(file);
    expect(result.ok).toBe(false);
  });
});
